# Generated by scripts/homebrew-formulas.py in tinhthanh/shipyard for v0.3.31-fork.4.
class Vetgo < Formula
  desc "Run coding agents on your own boxes: the berth CLI and laptop agent"
  homepage "https://github.com/tinhthanh/shipyard"
  version "0.3.31-fork.4"
  license "MIT"

  on_macos do
    on_arm do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.4/berth-darwin-arm64.tar.gz"
      sha256 "36c947b1b7c530598c6f396d0768c4607fe5cf54843521e4b5512ef11a7a0bfa"
    end
    on_intel do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.4/berth-darwin-amd64.tar.gz"
      sha256 "7276c74bb28ef91451d6dc54641d3ce5422f9b91f143e27daf7558c08b93f1df"
    end

    # The berthd builds `berth upgrade` puts on Mac boxes; the Linux ones
    # come in berth's own archive.
    resource "berthd-darwin-arm64" do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.4/berthd-darwin-arm64.tar.gz"
      sha256 "fd7be74f4c8223070f871332850ce3748c54d5d68dcdc36242671b8b15e63640"
    end
    resource "berthd-darwin-amd64" do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.4/berthd-darwin-amd64.tar.gz"
      sha256 "86c80cbde0d902cf8305866dbf3d161d9ee5a38c9fe06c6a32bc874347f919f1"
    end
  end
  on_linux do
    on_arm do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.4/berth-linux-arm64.tar.gz"
      sha256 "e5aaed1eb84af40bf166a7891e415197b58e0e7707df447740dfaa4c9edebe82"
    end
    on_intel do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.4/berth-linux-amd64.tar.gz"
      sha256 "8b28de95168ed5d72d339366c80f85ae2535f971a78dff455840cab1a662dd9f"
    end
  end

  def install
    # berth looks beside its own file (through the link in bin) for the
    # berthd and tmux builds it uploads to boxes.
    libexec.install Dir["*"]
    if OS.mac?
      %w[arm64 amd64].each do |arch|
        resource("berthd-darwin-#{arch}").stage { libexec.install "berthd" => "berthd-darwin-#{arch}" }
      end
    end
    bin.install_symlink libexec/"berth"
  end

  def caveats
    <<~EOS
      Start the laptop agent, and have it start when you log in:
        berth agent install
      Add a box: berth add ssh USER@HOST (see berth help).
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/berth version")
  end
end
